async function overlap(f:Awaited<ReturnType<typeof refundFixture>>,jobs:(()=>Promise<any>)[],order:number[],payment=false){const blocker=h.connect('crm_h0_migration');await blocker.unsafe('begin');if(payment)await blocker`select pg_advisory_xact_lock(hashtextextended(${'payment-root:'+f.a.paymentId},0))`;else await blocker`select pg_advisory_xact_lock(hashtextextended(${f.c.b.opportunityId},31))`;const pending:Promise<any>[]=[];try{for(let i=0;i<order.length;i++){pending.push(jobs[order[i]!]!().then(value=>({ok:true,value}),error=>({ok:false,error:error.message})));let count=0;for(let n=0;n<150;n++){count=Number((await h.admin`select count(*)::int n from pg_stat_activity where usename in('crm_h0_runtime','crm_h0_ha_tx')and wait_event_type='Lock'`)[0]!.n);if(count>=i+1)break;await delay(10);}console.log('H4-016 observed independent PostgreSQL Lock sessions',order,'queued',i+1,'observed',count);assert.ok(count>=i+1);}await blocker.unsafe('rollback');return await Promise.all(pending);}finally{await blocker.unsafe('rollback');await blocker.end();}}
