 const metadata=lstatSync(resolve(root,path));assert.ok(metadata.isFile()&&!metadata.isSymbolicLink(),path+': F14 regular file');
 assert.equal(metadata.mode&0o777,0o644,path+': F14 exact permissions');
 const original=execFileSync('git',['show',f14Transition.baseCommit+':'+path],{cwd:root});
 assert.equal(original.length,f14Transition.historicalBytes,path+': published F14 original size');
 assert.equal(digest(original),f14Transition.historicalSha256,path+': published F14 original');
 const hash=digest(current);assert.equal(digest(readFileSync(resolve(root,path))),hash,path+': F14 on-disk bytes');
 assert.ok(hash===f14Transition.historicalSha256||hash===f14Transition.correctedSha256,path+': unauthorized F14 third version');
 assert.equal(current.length,hash===f14Transition.historicalSha256?f14Transition.historicalBytes:f14Transition.correctedBytes,path+': F14 exact size');
 if(hash===f14Transition.correctedSha256){
  const expected=readFileSync(resolve(root,'specs/001-core-crm/expected-TSK-H5-011-012.md'));
  assert.equal(expected.length,67346);assert.equal(digest(expected),f14Transition.expectedSha256,path+': F14 isolated expected');
  const record=resolve(root,'tests/fixtures/h5-011/f14-20261014/transition.authorized.json'),stat=lstatSync(record);
  assert.ok(stat.isFile()&&!stat.isSymbolicLink());assert.equal(stat.mode&0o777,0o644);
  assert.deepEqual(JSON.parse(readFileSync(record,'utf8')),f14Transition,path+': exact F14 authorization record');
 }
 return true;
}

export function assertHistoricalBytes(path:string,current:Uint8Array,historical:Uint8Array):void {
 if(assertF14Transition(path,current,digest(historical),'.'))return;
 if(assertC12Transition(path,current,digest(historical),'.'))return;
 if(assertF09R52Transition(path,current,digest(historical),'.'))return;
 if(assertF07Transition(path,current,digest(historical),'.'))return;
 const exception=Object.hasOwn(f10DependencyHashes,path)?f10DependencyHashes[path]:undefined;
 if(!exception){assert.deepEqual(Buffer.from(current),Buffer.from(historical),path);return;}
 assert.equal(digest(historical),exception.historical,path+': historical dependencies changed');
 assert.equal(digest(current),exception.current,path+': outside exact F10 dependency patch');
 console.log('H5-006 F10 exact dependency exception',JSON.stringify({path,...exception}));
}

